import{_ as e,o as i,c as s,ag as n}from"./chunks/framework.CrXGS008.js";const z=JSON.parse('{"title":"Repair Station Business","description":"","frontmatter":{},"headers":[],"relativePath":"pl/repair-station-business/index.md","filePath":"pl/repair-station-business/index.md"}'),t={name:"pl/repair-station-business/index.md"};function o(r,a,c,l,p,d){return i(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="repair-station-business" tabindex="-1">Repair Station Business <a class="header-anchor" href="#repair-station-business" aria-label="Permalink to &quot;Repair Station Business&quot;">​</a></h1><p>Płatny dodatek do <a href="/pl/repair-station/">Repair Station</a>: gracze kupują stacje napraw, zaopatrują je w części, ustalają ceny i odbierają utarg z kasy. Wszystkim zarządza się z tabletu na stacji, a każde ustawienie edytuje się w grze.</p><h2 id="funkcje" tabindex="-1">Funkcje <a class="header-anchor" href="#funkcje" aria-label="Permalink to &quot;Funkcje&quot;">​</a></h2><ul><li><strong>Stacje na sprzedaż</strong>: wybierasz, które Repair Station można kupić i za ile. Zobacz <a href="/pl/repair-station-business/ownership">Własność</a>.</li><li><strong>Tablet właściciela</strong>: magazyn, kasa, ostatnie operacje, ceny, nazwa i sprzedaż stacji w jednym miejscu.</li><li><strong>Części</strong>: każda naprawa zużywa części z magazynu stacji, kupowane z konta bankowego lub oddawane jako przedmioty. Zobacz <a href="/pl/repair-station-business/stock">Magazyn</a>.</li><li><strong>Ceny właściciela</strong>: każdy właściciel ustawia procent ceny bazowej w granicach, które wybierzesz, a od każdej płatności pobierany jest podatek.</li><li><strong>Uczciwe zakończenia</strong>: właściciel, który sprzeda stację, zostanie usunięty lub stanie się nieaktywny, dostaje zwrot części ceny zakupu plus kasę, także offline.</li><li><strong>Panel administratora</strong>: wystawiaj stacje na sprzedaż, zmieniaj ich cenę, ustawiaj magazyn stacji z właścicielem lub usuwaj właściciela, nie wychodząc z gry.</li><li><strong>API HTTP i webhooki</strong>: stacje, rejestr i statystyki dla twojej strony oraz wiadomość na Discordzie przy każdym zakupie, uzupełnieniu, wypłacie i utracie stacji. Zobacz <a href="/pl/repair-station-business/api">API i webhooki</a>.</li><li><strong>Sześć języków</strong>: angielski, francuski, hiszpański, portugalski, polski, niemiecki.</li></ul><h2 id="zgodnosc" tabindex="-1">Zgodność <a class="header-anchor" href="#zgodnosc" aria-label="Permalink to &quot;Zgodność&quot;">​</a></h2><ul><li>Frameworki: ESX Legacy, QBCore, QBox, ox_core, wykrywane automatycznie.</li><li>Zależności: oxmysql, <code>nay_lib</code> i <a href="/pl/repair-station/">Repair Station</a> (<code>nay_repair</code>), dołączone do zakupu skryptów.</li></ul><h2 id="instalacja" tabindex="-1">Instalacja <a class="header-anchor" href="#instalacja" aria-label="Permalink to &quot;Instalacja&quot;">​</a></h2><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ensure oxmysql</span></span>
<span class="line"><span>ensure nay_lib</span></span>
<span class="line"><span>ensure nay_repair</span></span>
<span class="line"><span>ensure nay_repair_business</span></span></code></pre></div><p>Pełne kroki znajdziesz na stronie <a href="/pl/getting-started">Pierwsze kroki</a>. Następnie nadaj sobie <code>nay_repair_business.config</code> (lub <code>nay.admin</code>) i otwórz <code>/nay</code>, albo wpisz <code>/nay:repairbusiness</code>, aby otworzyć panel administratora. Zaznacz w panelu stacje, które chcesz sprzedawać: do tego czasu stacje działają jak zwykłe Repair Station.</p>`,9)])])}const k=e(t,[["render",o]]);export{z as __pageData,k as default};
